+	public void setIcon(ItemStack icon) {
+		this.icon = icon;
+	}
+
+	@Override
+	public ItemStack createIcon() {
+		ItemStack supplierIcon = this.iconSupplier.get();
+		if (!supplierIcon.isEmpty()) {
+			return supplierIcon;
+		} else if (icon == null) {
+			return ItemStack.EMPTY;
+		}
+
+		return icon;
+	}
+
+	@Override
