+            return Optional.of(resource);
+        }
+        // if not, check for experience fragments and resolve them
+        if (resource.isResourceType(com.adobe.cq.wcm.core.components.internal.models.v1.ExperienceFragmentImpl.RESOURCE_TYPE_V1)
