+        // if not iterate over the resource's children
+        for (Resource child : resource.getChildren()) {
+            Optional<Resource> result = findFirst(child, condition, containingPage);
+            if (result.isPresent()) {
+                return result;
+            }
+        }
+
+        return Optional.empty();
+    }
