+                request.getService(),
+                request.getTransportHeaders(),
+                serializer.encodeEndpoint(request.getEndpoint(), scheme),
+                serializer.encodeHeaders(request.getHeaders(), scheme),
+                serializer.encodeBody(request.getBody(), scheme)
+        );
