+    ) throws InterruptedException, TChannelError {
+        return callWithEncoding(host, port, request, responseType, ArgScheme.THRIFT);
+    }
+
+    public <T, U> ListenableFuture<Response<T>> callThrift(
+        Request<U> request,
+        final Class<T> responseType
+    ) throws InterruptedException, TChannelError {
