+    assertThat(metadata.getAuthKey()).isEqualTo((short) 1);
+    assertThat(metadata.getOpaqueObjId()).isEqualTo((short) 5);
+    assertThat(metadata.getKeyType()).isEqualTo(KeyType.BLS);
