+	switch tran {
+	case mockProposed:
+		return "Proposed"
+	case mockPreVoted:
+		return "PreVoted"
+	case mockPreCommitted:
+		return "PreCommitted"
+	case mockImmediate:
+		return "TimedOut"
+	default:
+		return "FIXME, Not a mockTran"
+	}
