+func newMock() *mockInput {
+	return &mockInput{
+		height:       0,
+		rnd:          rand.New(rand.NewSource(time.Now().UnixNano())),
+		Map:          make(map[block.Height]mockTran),
+		GotImmediate: false,
+	}
+}
