      "effect": "ALLOW",
      "actions": [ "iam:teams:list" ],
      "projects": [ "p2" ]
    },
  {
      "effect": "ALLOW",
      "actions": [ "iam:roles:list" ],
      "projects": [ "*" ]
    },
