+  const queryString = qs.stringify({
+    client_id: process.env.CLICKUP_CLIENT_ID,
+    redirect_uri: `${process.env.FRONTEND_URL}/api/backend/v1/clickup/callback`,
+    state: getSignedState(userId, process.env.CLICKUP_OAUTH_SECRET),
+  });
