+        for (int keyDist = 0; keyDist < entries.length; keyDist++) {
+            int curIdx = (idx + keyDist) & (entries.length - 1);
+
+            Entry<V> entry = entries[curIdx];
+
+            if (entry == null)
+                return -1;
+            else if (entry.key == key)
+                return curIdx;
+
+            int entryDist = distance(curIdx, entry.key);
+
+            if (keyDist > entryDist)
+                return -1;
+        }
+
+        return -1;
+    }
