+        entries = (Entry<V>[])new Entry[newCap];
+
+        compactThreshold = (int)(COMPACT_LOAD_FACTOR * (entries.length >> 1));
+
+        scaleThreshold = (int)(entries.length * SCALE_LOAD_FACTOR);
+
+        size = 0;
+
+        for (Entry<V> entry : oldEntries)
+            if (entry != null)
