+
+		// Create some messages in the mailbox.
+		messageID1 := s.messageCreatedFromFile("user", mailboxID, "testdata/multipart-mixed.eml")
+		s.messageCreatedFromFile("user", mailboxID, "testdata/afternoon-meeting.eml")
+
