+import { fileURLToPath } from 'node:url';
+
+import { Miniflare, Request } from 'miniflare';
+
+/**
+ * @typedef {Response} ExtendedResponse
+ * @property {function(string): string|undefined} getHeader Method to access a header (alias to headers.get).
+ * @property {Request} request Request that was sent to fetch the response.
+ * @property {string} text Text content from the response.
+ * @property {ReadableStream|*} body Body content from the response (parsed JSON if response declared as JSON).
+ */
+
+/**
+ * Dispatch a fetch request to Miniflare.
+ *
+ * @param {string} route Route to request in API via Miniflare.
+ * @param {RequestInit} [opts={}] Options to set for fetch request.
+ * @return {ExtendedResponse}
+ */
+export default (route, opts = {}) => {
+    // Create the Miniflare instance
+    const mf = new Miniflare({
+        scriptPath: fileURLToPath(new URL('../../../dist-worker/index.js', import.meta.url)),
+        wranglerConfigPath: fileURLToPath(new URL('../../../wrangler.toml', import.meta.url)),
+        host: 'localhost',
+        port: 5050,
+    });
+
+    // Create a full request
+    const req = new Request(`http://localhost:5050${route}`, opts);
+
+    // Send the request to Miniflare
+    return mf.dispatchFetch(req).then(async resp => {
+        // Patch in some extras for chai-http
+
+        /**
+         * Fetch a header from the response.
+         *
+         * @param {string} name Name of the header to fetch.
+         * @return {string}
+         */
+        resp.getHeader = name => resp.headers.get(name);
+
+        // Expose the request
+        resp.request = req;
+
+        // Replace the text method (returns a promise that consumes the body stream)
+        // chai-http expects the text property to be the text content
+        const text = await resp.text();
+        Reflect.defineProperty(resp, 'text', { value: text });
+
+        // Replace the body property (is a readable stream of the body)
+        // chai-http expects the body property to be the parsed body JSON data
+        // https://github.com/visionmedia/superagent/blob/9ed29166e2fe01d20a1ae4c06e009b1a27711c27/src/client.js#L275-L287
+        if (/[/+]json($|[^-\w])/i.test(resp.headers.get('content-type')?.toLowerCase()))
+            Reflect.defineProperty(resp, 'body', { value: JSON.parse(text) });
+
+        return resp;
+    });
+};

## PR Title
Use runtime delegate to parse function triggers in the Functions Emulator

## PR Description
Today, Functions Emulator parses function trigger from source as follows:

1) Spin up an instance of Functions runtime process
2) Invoke a "function" which triggers a path that parses the trigger by calling out to `extractTriggers.js`
3) Send parsed triggers via IPC from runtime to emulator. Emulator now knows about the triggers.

This has the advantage of running the trigger parsing in the emulated runtime (which properly mocks out calls to the DB, applies network filtering, uses the same node version when possible, etc.) but has the disadvantage of complicating the runtime implementation as well as diverging from how the triggers are parsed in `firebase deploy`.

Using runtime delegate, we have:

1) Use runtime delegate to discover the delegate appropriate for function source (i.e. Node, but in the future can be some other runtime)
2) Spin up a node subprocess to parse trigger. Emulator now knows about the triggers.

i.e. the same procedure used during `firebase deploy`

By using runtime delegate, we align the function deploy to production and to the emulated environment and simplify the runtime code a bit. This also puts us into a good position in the future when we make the function deploy process a little more complex, e.g. params and secrets support.

One missing feature that could not be ported nicely here is soft-enforcement of function timeouts. I wanted to leave it out until I make further refinement in the Functions Emulator to make function invocation simpler. It will be made up in a subsequent PR.

